list_cities.code:
final response = await client.cities
    .listCities(queryParams: {'country': 'AU', 'state': 'VIC', 'limit': 20});
final body = response.map as Map;
for (final city in body['cities'] as List) {
  print('${(city as Map)['name']} ${city['post_code']}');
}
print((body['pagination'] as Map)['total']);

